CREATE TABLE IF NOT EXISTS crm_eventos (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, nome_evento VARCHAR(180) NOT NULL, data_evento DATE NOT NULL, ativo TINYINT(1) NOT NULL DEFAULT 1, created_by VARCHAR(120) NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_crm_eventos_data (data_evento)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS crm_evento_importacoes (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, evento_id BIGINT NOT NULL, nome_arquivo VARCHAR(255) NOT NULL, extensao VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PREVIEW', total_linhas INT NOT NULL DEFAULT 0, linhas_validas INT NOT NULL DEFAULT 0, linhas_invalidas INT NOT NULL DEFAULT 0, linhas_duplicadas INT NOT NULL DEFAULT 0, mapeamento_json LONGTEXT NULL, created_by VARCHAR(120) NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_evento (evento_id), CONSTRAINT fk_evento_import FOREIGN KEY (evento_id) REFERENCES crm_eventos(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS crm_evento_participantes (id BIGINT AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, evento_id BIGINT NOT NULL, importacao_id BIGINT NOT NULL, nome VARCHAR(150) NOT NULL, telefone VARCHAR(30) NULL, email VARCHAR(150) NULL, empresa VARCHAR(150) NULL, cnpj VARCHAR(18) NULL, chave_deduplicacao VARCHAR(190) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, KEY idx_part_evento (evento_id), KEY idx_part_chave (evento_id,chave_deduplicacao), CONSTRAINT fk_part_evento FOREIGN KEY (evento_id) REFERENCES crm_eventos(id) ON DELETE CASCADE, CONSTRAINT fk_part_import FOREIGN KEY (importacao_id) REFERENCES crm_evento_importacoes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;